function Invoke-Captured {
 param([string]$Label,[string]$Exe,[string[]]$Vector,[string]$Cwd)
 $dir=Join-Path $base "$Label";[IO.Directory]::CreateDirectory($dir)|Out-Null
 [IO.File]::WriteAllText((Join-Path $dir 'argv.json'),(@{executable=$Exe;workingDirectory=$Cwd;arguments=$Vector}|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false))
 $psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$Exe;$psi.WorkingDirectory=$Cwd;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;foreach($a in $Vector){[void]$psi.ArgumentList.Add($a)}
 $p=[Diagnostics.Process]::new();$p.StartInfo=$psi;$sw=[Diagnostics.Stopwatch]::StartNew();if(-not $p.Start()){throw "Process failed to start: $Label"};$ot=$p.StandardOutput.ReadToEndAsync();$et=$p.StandardError.ReadToEndAsync();$p.WaitForExit();$exit=$p.ExitCode;$sw.Stop();$out=$ot.GetAwaiter().GetResult();$err=$et.GetAwaiter().GetResult()
 [IO.File]::WriteAllText((Join-Path $dir 'stdout.log'),$out,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $dir 'stderr.log'),$err,[Text.UTF8Encoding]::new($false));$r=[ordered]@{exitCode=$exit;elapsedSeconds=[Math]::Round($sw.Elapsed.TotalSeconds,3);stdoutBytes=[Text.Encoding]::UTF8.GetByteCount($out);stderrBytes=[Text.Encoding]::UTF8.GetByteCount($err)};[IO.File]::WriteAllText((Join-Path $dir 'result.json'),($r|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false));return [pscustomobject]$r
}
